import {HOMES,AVATARS,STATUSES} from './social-catalog.mjs?v=27';
import {ROAD,BLOCKS,DISTRICTS} from './driving.mjs?v=27';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,tab='friends',selected=null,initialized=false,busy=false,generation=0;
function notice(message,error=false){$('crewNotice').textContent=message;$('crewNotice').classList.toggle('error',error);$('crewNotice').hidden=!message;}
async function api(path,method='GET',body){const response=await fetch('/api/'+path,{method,headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok){const error=new Error(data.error||'Crew is unavailable. Please try again.');error.status=response.status;throw error;}return data;}
async function load(quiet=false){const current=++generation;try{const next=await api('social');if(current!==generation)return false;if(state?.profile?.id!==next.profile?.id){initialized=false;selected=null;}state=next;$('signInPanel').hidden=true;$('crewWorkspace').hidden=false;if(!initialized){fillProfile();initialized=true;}render();if(!quiet)notice(state.profile?'':'Choose a name, character, and apartment to create your player profile.');return true;}catch(error){if(current!==generation)return false;if(error.status===401){state=null;selected=null;initialized=false;$('profileForm').reset();$('friendsList').replaceChildren();$('socialMap').replaceChildren();$('mapSelection').replaceChildren();$('friendCode').textContent='';$('signInPanel').hidden=false;$('crewWorkspace').hidden=true;notice('');}else notice(error.message,true);return false;}}
function fillProfile(){const p=state.profile||{name:'',avatar:'jules',status:'off-duty',note:'',homeId:'last-exit'};$('playerName').value=p.name;$('playerNote').value=p.note;$('playerStatus').innerHTML=STATUSES.map(s=>`<option value="${s.id}">${s.label}</option>`).join('');$('playerStatus').value=p.status;$('playerHome').innerHTML=HOMES.map(h=>`<option value="${h.id}">${h.name}</option>`).join('');$('playerHome').value=p.homeId;$('avatarChoices').innerHTML=AVATARS.map(a=>`<label title="${a}"><input type="radio" name="avatar" value="${a}" ${a===p.avatar?'checked':''} required><img src="/assets/site/characters/${a}.png" alt="${a}"></label>`).join('');$('myAvatar').src='/assets/site/characters/'+p.avatar+'.png';}
function render(){const p=state.profile;$('saveProfile').textContent=p?'SAVE PROFILE':'CREATE PLAYER PROFILE';$('friendCodeBox').hidden=!p;if(p)$('friendCode').textContent=p.friendCode.match(/.{1,4}/g).join(' ');$('addFriendForm').querySelectorAll('input,button').forEach(el=>el.disabled=!p);$('myPresence').textContent=p?'YOUR CHARACTER / '+p.name:'PLAYER PROFILE';$('friendsCount').textContent=state.friends.length;$('requestsCount').textContent=state.incoming.length+state.outgoing.length;renderList();renderMap();}
const avatar=p=>`<img class="friend-avatar" src="/assets/site/characters/${esc(p.avatar)}.png" alt="${esc(p.name)}'s character" width="640" height="800">`;
function friendCard(p){const home=HOMES.find(h=>h.id===p.homeId),status=STATUSES.find(s=>s.id===p.status);return `<article class="friend-card">${avatar(p)}<div class="friend-detail"><h3>${esc(p.name)}</h3><span class="presence ${p.online?'online':''}">${p.online?'Online in Crew':'Offline'}</span><p class="friend-status">${esc(status?.label)}${p.note?' · '+esc(p.note):''}</p><button class="home-link" data-home="${p.id}">${esc(home?.name)} ↗</button></div><button class="remove-friend" data-remove="${p.connectionId}" aria-label="Remove ${esc(p.name)} from friends">Remove</button></article>`;}
function requestCard(p,incoming){return `<article class="request-card">${avatar(p)}<div><h3>${esc(p.name)}</h3><span>${incoming?'Wants to join your crew':'Request sent'}</span></div><div class="request-actions">${incoming?`<button class="small-button" data-accept="${p.connectionId}">ACCEPT</button><button class="quiet-button" data-decline="${p.connectionId}">Decline</button>`:`<button class="quiet-button" data-cancel="${p.connectionId}">Cancel</button>`}</div></article>`;}
function renderList(){document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});$('friendsList').setAttribute('aria-labelledby',tab==='friends'?'tabFriends':'tabRequests');if(tab==='friends')$('friendsList').innerHTML=state.friends.length?state.friends.map(friendCard).join(''):`<div class="crew-empty"><span>YOUR PEOPLE GO HERE.</span><h3>${state.profile?'Every crew starts with one friend.':'Make your first player card.'}</h3><p>${state.profile?'Share your code or send a request above. Accepted friends and their apartments appear here.':'Create your profile, then invite someone you know.'}</p></div>`;else $('friendsList').innerHTML=state.incoming.length+state.outgoing.length?`<h3 class="list-label">RECEIVED / ${state.incoming.length}</h3>${state.incoming.map(p=>requestCard(p,true)).join('')||'<p class="empty-line">No incoming requests.</p>'}<h3 class="list-label">SENT / ${state.outgoing.length}</h3>${state.outgoing.map(p=>requestCard(p,false)).join('')||'<p class="empty-line">No sent requests.</p>'}`:'<div class="crew-empty"><h3>No requests yet.</h3><p>Requests you receive or send will show up here.</p></div>';}
function renderMap(){const people=state.profile?[state.profile,...state.friends]:[];let person=people.find(p=>p.id===selected)||state.profile;selected=person?.id;const home=HOMES.find(h=>h.id===person?.homeId);$('socialMap').innerHTML=`<svg viewBox="-300 -300 600 600" aria-hidden="true"><rect x="-300" y="-300" width="600" height="600" fill="#133229"/>${BLOCKS.map(b=>`<rect x="${b.x-b.w/2}" y="${b.z-b.d/2}" width="${b.w}" height="${b.d}" fill="${b.park?'#70a957':'#2c5540'}"/>`).join('')}${ROAD.map(n=>`<path d="M-282 ${n}H282 M${n} -282V282" stroke="#17251f" stroke-width="9"/>`).join('')}${DISTRICTS.map(d=>`<text x="${d.x}" y="${d.z-48}" text-anchor="middle" fill="#c3d6a5" font-family="Arial" font-size="14">${esc(d.name)}</text>`).join('')}${people.map(p=>{const h=HOMES.find(h=>h.id===p.homeId);return `<circle cx="${h.x}" cy="${h.z}" r="8" fill="#bce481" stroke="#11281c" stroke-width="3"/>`;}).join('')}${home?`<circle cx="${home.x}" cy="${home.z}" r="16" fill="none" stroke="#ffdf77" stroke-width="4"/><path d="M${home.x} ${home.z-25}v-15" stroke="#ffdf77" stroke-width="3"/>`:''}</svg>`;
$('mapSelection').innerHTML=home?`<div><span>${person.id===state.profile.id?'YOUR APARTMENT':esc(person.name)+"'S APARTMENT"}</span><h3>${esc(home.name)}</h3><p>${esc(home.description)}</p></div><a class="button" href="/play/?friendHome=${home.id}">SET GAME ROUTE ↗</a>`:'<p>Create your profile to put your apartment on the map.</p>';$('homePins').innerHTML=people.map(p=>`<button data-home="${p.id}" aria-pressed="${p.id===selected}">${esc(p.name)}${p.id===state.profile.id?' (you)':''}</button>`).join('');}
async function mutate(fn,message){if(busy)return;busy=true;generation++;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{await fn();if(await load(true))notice(message);}catch(error){notice(error.message,true);}finally{busy=false;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);if(!state?.profile)$('addFriendForm').querySelectorAll('input,button').forEach(el=>el.disabled=true);}}
$('profileForm').addEventListener('change',e=>{if(e.target.name==='avatar')$('myAvatar').src='/assets/site/characters/'+e.target.value+'.png';});
$('profileForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));mutate(()=>api('profile','PUT',data),'Profile saved. Your crew can see your latest status and apartment.');});
$('addFriendForm').addEventListener('submit',e=>{e.preventDefault();mutate(async()=>{await api('requests','POST',{code:$('friendCodeInput').value});$('friendCodeInput').value='';tab='requests';},'Friend request sent.');});
$('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(state.profile.friendCode);notice('Friend code copied. Send it to someone you know.');}catch{notice('Copy your code from the player card.');}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||busy)return;if(b.dataset.tab){tab=b.dataset.tab;renderList();}if(b.dataset.home){selected=b.dataset.home;renderMap();$('socialMap').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});}if(b.dataset.accept)mutate(()=>api('requests/'+b.dataset.accept,'PATCH',{action:'accept'}),'Friend added. Their apartment is now on your map.');if(b.dataset.decline)mutate(()=>api('requests/'+b.dataset.decline,'PATCH',{action:'decline'}),'Request declined.');if(b.dataset.cancel)mutate(()=>api('requests/'+b.dataset.cancel,'DELETE'),'Request cancelled.');if(b.dataset.remove){const id=b.dataset.remove;b.replaceWith(Object.assign(document.createElement('button'),{className:'quiet-button',textContent:'Confirm remove',onclick:()=>mutate(()=>api('friends/'+id,'DELETE'),'Friend removed. Your status and home are no longer shared.')}));}});
document.querySelector('.friends-tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();tab=e.key==='Home'?'friends':e.key==='End'?'requests':tab==='friends'?'requests':'friends';renderList();$(tab==='friends'?'tabFriends':'tabRequests').focus();}});
async function heartbeat(){if(document.hidden||busy||!state?.profile)return;try{await api('presence','POST');await load(true);}catch{}}
await load();await heartbeat();setInterval(heartbeat,45000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)heartbeat();});
